import{_ as l,a0 as n,w as a,s as Z,ao as i,I as t,a1 as s,A as p,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"树莓派 Zero 与 Zero W 对比 | LCTT x X-CMD","titleTemplate":false,"description":"树莓派 Zero 与 Zero W 对比 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"树莓派 Zero 与 Zero W 对比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"树莓派 Zero 与 Zero W 对比 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference","title":"树莓派 Zero 与 Zero W 对比","tag":"202109","desc":""},"relativePath":"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference.md","filePath":"[post].md"}'),f={name:"202109/20210915 Raspberry Pi Zero vs Zero W- What-s the Difference.md"};function u(m,r,d,b,W,T){const o=n("Link");return a(),Z("div",null,[r[28]||(r[28]=i('<h1 id="树莓派-zero-与-zero-w-对比" tabindex="-1">树莓派 Zero 与 Zero W 对比 <a class="header-anchor" href="#树莓派-zero-与-zero-w-对比" aria-label="Permalink to “树莓派 Zero 与 Zero W 对比”">​</a></h1><p>树莓派十年前凭借 25 美元的迷你电脑掀起了一场革命。随着时间的推移，树莓派发布了许多变种。有些是对以前的型号进行升级，有些是为特定目的而制作的。</p><p>在所有的树莓派模块中，Pi Zero 和 Pi Zero W 是最便宜的型号，旨在用于小规模项目和 IoT 项目。这两种设备几乎是相同的，但是它们之间有一些微妙而重要的区别。</p><p><strong>那么，树莓派 Zero 和 Zero W 之间的区别是什么？Zero W 中的 W 代表的是<ruby>无线<rt>Wireless</rt></ruby>，它表示的是 Zero W 模块拥有无线功能。这是这两个相似模块之间的最大差异。</strong></p><p>让我们来详细了解一下。</p><h3 id="pi-zero-与-pi-zero-w-之间的主要不同点" tabindex="-1">Pi Zero 与 Pi Zero W 之间的主要不同点 <a class="header-anchor" href="#pi-zero-与-pi-zero-w-之间的主要不同点" aria-label="Permalink to “Pi Zero 与 Pi Zero W 之间的主要不同点”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-vs-zero-w.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>树莓派 Zero 是以在只有 A+ 板一半的大小上提供尽可能多的功能为目标。</p><p>而树莓派 Zero W 是为了支持无线在后来推出的，在不需要任何附加的组件和模块的情况下就可以使用蓝牙和 Wi-Fi。</p><p>这是两者之间的关键区别，其他的规格保持一致。</p><p>所以，如果你需要以下功能：</p><ul><li>802.11 b/g/n 无线网口</li><li>蓝牙 4.1</li><li>低功耗蓝牙（BLE）</li></ul><p>树莓派 Zero W 将是你的不二之选。</p><p>此外，树莓派 Zero W 还提供了一种带引脚的版本，叫做 “树莓派 Pi Zero WH”</p><h3 id="树莓派-zero-和-zero-w-的规格" tabindex="-1">树莓派 Zero 和 Zero W 的规格 <a class="header-anchor" href="#树莓派-zero-和-zero-w-的规格" aria-label="Permalink to “树莓派 Zero 和 Zero W 的规格”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-w.png?resize=600%2C400&amp;ssl=1" alt="Raspberry Pi Zero W"></p>',16)),t("p",null,[s(o,{href:"https://itsfoss.com/raspberry-pi-zero-w/"},{default:p(()=>[...r[0]||(r[0]=[e("树莓派 Zero 和 Zero W 的规格",-1)])]),_:1}),r[1]||(r[1]=e(" 几乎是一样的。",-1))]),r[29]||(r[29]=t("p",null,"它们都具有 1 GHz 的单核 CPU 和 512 MB 的 RAM。至于接口方面，一个 mini HDMI 接口，支持 micro USB OTG、micro USB 供电和一个 CSI 摄像头接口（用于插入一个相机模块）。",-1)),t("p",null,[r[3]||(r[3]=e("这些板子会提供一种叫 ",-1)),s(o,{href:"https://github.com/raspberrypi/hats"},{default:p(()=>[...r[2]||(r[2]=[e("HAT",-1)])]),_:1}),r[4]||(r[4]=e("（",-1)),r[5]||(r[5]=t("ruby",null,[e("顶部附加硬件"),t("rt",null,"Hardware Attached on Top")],-1)),r[6]||(r[6]=e("）兼容的 40 个引脚。但一般情况下，没有这些可以让你轻松插入接口的引脚。",-1))]),t("p",null,[r[8]||(r[8]=e("你可以根据自己的功能需要选择使用 ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-os/"},{default:p(()=>[...r[7]||(r[7]=[e("各种树莓派兼容的系统",-1)])]),_:1}),r[9]||(r[9]=e("，但无论哪种情况，我还是推荐你使用树莓派 OS。",-1))]),r[30]||(r[30]=i('<h3 id="树莓派-zero-系列值不值得买" tabindex="-1">树莓派 Zero 系列值不值得买？ <a class="header-anchor" href="#树莓派-zero-系列值不值得买" aria-label="Permalink to “树莓派 Zero 系列值不值得买？”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/raspberry-pi-zero-1.png?resize=600%2C400&amp;ssl=1" alt="Raspberry Pi Zero"></p><p>树莓派 Zero 是一种很受人们喜欢的单片机形式，即使你有很多树莓派 Zero 的替代品，树莓派 Zero 仍然是最推荐的选择。</p><p>当然，除非你有特殊需求。</p><p>除了板子的尺寸之外，定价、功率要求、运算能力也是这款 20 美元以下的板子的主要亮点。</p><p>因此，如果你正在寻找预算内满足基本功能的单片机，树莓派 Zero 就是专门为你打造的。</p><h3 id="树莓派-zero-系列价格怎么样" tabindex="-1">树莓派 Zero 系列价格怎么样？ <a class="header-anchor" href="#树莓派-zero-系列价格怎么样" aria-label="Permalink to “树莓派 Zero 系列价格怎么样？”">​</a></h3><p>树莓派 Zero 售价 <strong>5 美元</strong> ，Zero W 售价 <strong>10 美元左右</strong>，当然，根据其供应情况和地区，定价规则会不一样，如果你选择带引脚的版本树莓派 Zero WH ，售价大概是 <strong>14 美元</strong> 左右。</p>',8)),t("p",null,[r[11]||(r[11]=e("还有 ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-zero-alternatives/"},{default:p(()=>[...r[10]||(r[10]=[e("其他的设备可以代替树莓派 Zero",-1)])]),_:1}),r[12]||(r[12]=e("，它们价格也相差不大。",-1))]),r[31]||(r[31]=t("hr",null,null,-1)),t("p",null,[r[14]||(r[14]=e("via: ",-1)),s(o,{href:"https://itsfoss.com/raspberry-pi-zero-vs-zero-w/"},{default:p(()=>[...r[13]||(r[13]=[e("https://itsfoss.com/raspberry-pi-zero-vs-zero-w/",-1)])]),_:1})]),t("p",null,[r[19]||(r[19]=e("作者：",-1)),s(o,{href:"https://itsfoss.com/author/ankush/"},{default:p(()=>[...r[15]||(r[15]=[e("Ankush Das",-1)])]),_:1}),r[20]||(r[20]=e(" 选题：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:p(()=>[...r[16]||(r[16]=[e("lujun9972",-1)])]),_:1}),r[21]||(r[21]=e(" 译者：",-1)),s(o,{href:"https://github.com/anine09"},{default:p(()=>[...r[17]||(r[17]=[e("anine09",-1)])]),_:1}),r[22]||(r[22]=e(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:p(()=>[...r[18]||(r[18]=[e("wxy",-1)])]),_:1})]),t("p",null,[r[25]||(r[25]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...r[23]||(r[23]=[e("LCTT",-1)])]),_:1}),r[26]||(r[26]=e(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:p(()=>[...r[24]||(r[24]=[e("Linux中国",-1)])]),_:1}),r[27]||(r[27]=e(" 荣誉推出",-1))])])}const C=l(f,[["render",u]]);export{g as __pageData,C as default};
